/*-------------------------------------------------------------------------
 *
 * generate_keyword_index.cpp
 *	  Writes kwlist_index.hpp, the open-addressed hash index over kwlist.hpp
 *	  that ScanKeywordLookup() probes.
 *
 * The index stores positions in the keyword array, so it is only valid for the
 * kwlist.hpp it was generated from. It is committed rather than generated by
 * the build; regenerate it after editing kwlist.hpp:
 *
 *     make -C build/<type> sql_digest_keyword_index
 *     ./build/<type>/extension/sql_digest/third_party/libpg_query_digest/\
 *         sql_digest_keyword_index \
 *         extension/sql_digest/third_party/libpg_query_digest/kwlist_index.hpp
 *
 * The index is checked against the binary search before it is written; a
 * stale committed index fails the keyword checks in sql_digest.test.
 *
 * Writes the header to the path supplied as its only argument.
 *
 *-------------------------------------------------------------------------
 */
#include "pg_functions.hpp"
#include <string.h>
#include <string>
#include <memory>
#include "parser/gramparse.hpp"

#define DUCKDB_BASE_STD

namespace duckdb_base_std {
using ::std::unique_ptr;
} // namespace duckdb_base_std

/* pg_functions.hpp defines fprintf away; this tool needs it for its messages. */
#undef fprintf

#include "parser/kwlist.hpp"
#include "parser/kwlist_lookup.hpp"

#include <cerrno>
#include <cstdio>
#include <vector>
#include <string>

namespace duckdb_sql_digest_pgquery {
namespace {

int SlotCountFor(int num_keywords) {
	int slot_count = 1;
	while (slot_count < num_keywords * PG_KEYWORD_INDEX_SLOTS_PER_KEYWORD) {
		slot_count *= 2;
	}
	return slot_count;
}

} // namespace
} // namespace duckdb_sql_digest_pgquery

int main(int argc, char *argv[]) {
	using namespace duckdb_sql_digest_pgquery;

	if (argc != 2) {
		fprintf(stderr, "usage: %s OUTPUT\n", argv[0]);
		return 1;
	}
	const char *output_path = argv[1];
	std::string temporary_path = std::string(output_path) + ".tmp";

	if (NumScanKeywords > INT16_MAX) {
		fprintf(stderr, "the keyword table no longer fits an int16_t index\n");
		return 1;
	}

	int slot_count = SlotCountFor(NumScanKeywords);
	std::vector<int16_t> slots(slot_count, -1);
	std::string unreachable;
	int max_length = 0;

	for (int i = 0; i < NumScanKeywords; i++) {
		const char *name = ScanKeywords[i].name;
		for (const char *c = name; *c != '\0'; c++) {
			if (*c >= 'A' && *c <= 'Z') {
				fprintf(stderr,
				        "keyword \"%s\" is not lower case; the lookup down-cases "
				        "before it probes\n",
				        name);
				return 1;
			}
		}
		const PGScanKeyword *reachable = ScanKeywordBinarySearch(name, ScanKeywords, NumScanKeywords);
		if (reachable == NULL) {
			if (!unreachable.empty()) {
				unreachable += ", ";
			}
			unreachable += name;
			continue;
		}
		int length = (int)strlen(name);
		if (length > max_length) {
			max_length = length;
		}
		uint32_t slot = ScanKeywordHash(name, length) & (uint32_t)(slot_count - 1);
		while (slots[slot] != -1) {
			slot = (slot + 1) & (uint32_t)(slot_count - 1);
		}
		slots[slot] = (int16_t)(reachable - ScanKeywords);
	}

	/*
	 * Every keyword, and every word one edit away from one, has to reach the
	 * same entry through the index as through the binary search.
	 */
	long long checked = 0;
	for (int i = 0; i < NumScanKeywords; i++) {
		std::string word = ScanKeywords[i].name;
		std::vector<std::string> probes;
		probes.push_back(word);
		probes.push_back(word + "x");
		if (word.size() > 1) {
			probes.push_back(word.substr(0, word.size() - 1));
		}
		for (size_t at = 0; at < word.size(); at++) {
			for (const char *c = "abcdefghijklmnopqrstuvwxyz0123456789_"; *c != '\0'; c++) {
				std::string edited = word;
				edited[at] = *c;
				probes.push_back(edited);
			}
		}
		for (size_t j = 0; j < probes.size(); j++) {
			const char *w = probes[j].c_str();
			int length = (int)probes[j].size();
			const PGScanKeyword *hashed =
			    length > max_length ? NULL : ScanKeywordProbe(w, length, ScanKeywords, &slots[0], slot_count);
			const PGScanKeyword *searched = ScanKeywordBinarySearch(w, ScanKeywords, NumScanKeywords);
			if (hashed != searched) {
				fprintf(stderr,
				        "the keyword index disagrees with the binary search on \"%s\": "
				        "index says %s, search says %s\n",
				        w, hashed ? hashed->name : "(no match)", searched ? searched->name : "(no match)");
				return 1;
			}
			checked++;
		}
	}
	/* Keep the previous header intact until generation has succeeded. */
	if (freopen(temporary_path.c_str(), "w", stdout) == NULL) {
		fprintf(stderr, "cannot write %s: %s\n", temporary_path.c_str(), strerror(errno));
		return 1;
	}
	printf("/* Generated from kwlist.hpp by generate_keyword_index.cpp; do not edit.\n");
	printf(" * Regenerate it whenever kwlist.hpp changes (see that file).\n");
	printf(" *\n");
	if (unreachable.empty()) {
		printf(" * Every entry is reachable by the binary search and indexed.\n");
	} else {
		printf(" * Not indexed, because the binary search cannot reach them either:\n");
		printf(" *   %s\n", unreachable.c_str());
	}
	printf(" */\n\n");
	printf("#define PG_KEYWORD_INDEX_NUM_KEYWORDS %d\n", NumScanKeywords);
	printf("#define PG_KEYWORD_INDEX_SLOT_COUNT %d\n", slot_count);
	printf("#define PG_KEYWORD_INDEX_MAX_LENGTH %d\n", max_length);
	printf("\n/* position in the keyword array, or -1 for an empty slot */\n");
	printf("static const int16_t PGKeywordIndexSlots[PG_KEYWORD_INDEX_SLOT_COUNT] = {\n");
	for (int i = 0; i < slot_count; i++) {
		printf("%s%5d,", (i % 16 == 0) ? "    " : " ", slots[i]);
		if (i % 16 == 15) {
			printf("\n");
		}
	}
	printf("};\n");
	int flush_result = fflush(stdout);
	int write_error = flush_result == 0 ? 0 : errno;
	int close_result = fclose(stdout);
	if (close_result != 0) {
		write_error = errno;
	}
	if (flush_result != 0 || close_result != 0) {
		std::remove(temporary_path.c_str());
		fprintf(stderr, "cannot finish %s: %s\n", temporary_path.c_str(), strerror(write_error));
		return 1;
	}

#if defined(_WIN32)
	/* MSVC's rename() does not replace an existing file. */
	if (std::remove(output_path) != 0 && errno != ENOENT) {
		int rename_error = errno;
		std::remove(temporary_path.c_str());
		fprintf(stderr, "cannot replace %s: %s\n", output_path, strerror(rename_error));
		return 1;
	}
#endif
	if (std::rename(temporary_path.c_str(), output_path) != 0) {
		int rename_error = errno;
		std::remove(temporary_path.c_str());
		fprintf(stderr, "cannot replace %s: %s\n", output_path, strerror(rename_error));
		return 1;
	}

	/* printed only once the header is in place, so a failed run never reports success */
	fprintf(stderr,
	        "keyword index: %d of %d keywords in %d slots, longest %d, "
	        "%lld probes agree with the binary search\n",
	        (int)(NumScanKeywords - (unreachable.empty() ? 0 : 1)), NumScanKeywords, slot_count, max_length, checked);
	return 0;
}
